<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import FeedbackThread from '../components/FeedbackThread.vue';
import WebOperations from './WebOperations.vue';
const section=ref<'feedback'|'web'>('feedback');
import {feedbackAuthor} from '../platform/feedback-profile.ts';
import ModalDialog from '../components/ModalDialog.vue';
import {saveFeedbackDraft,newFeedbackDraft} from '../state/feedback-drafts.ts';
import {feedbackCall,onFeedbackNotification,feedbackTime,feedbackClientLabel,supportsFeedbackTrash,type FeedbackHealth,type FeedbackIdentity,type FeedbackSummary} from '../platform/feedback.ts';
interface Device{id:string;name:string;created:number}
interface Receiving{enabled:boolean;permission:boolean;batteryExempt:boolean}
const feedbackThread=ref<InstanceType<typeof FeedbackThread>>();
async function clearDeletedDraft(owner:string){try{if(selected.value===owner)await feedbackThread.value?.discardDraft();else await saveFeedbackDraft('admin:'+owner,newFeedbackDraft());}catch{error.value='会话已永久删除，本机草稿暂未清空。';}}
const connected=ref(false),server=ref('https://www.phonetictoolbox.com/api/v1/feedback'),token=ref(''),code=ref(''),error=ref(''),busy=ref(false),items=ref<FeedbackSummary[]>([]),selected=ref(''),search=ref(''),filter=ref('all'),dark=ref(localStorage.getItem('feedback-theme')==='dark'),mobile=ref(false),online=ref(false),settings=ref(false),pairCode=ref(''),pairExpires=ref(0),devices=ref<Device[]>([]),receiving=ref<Receiving>({enabled:false,permission:false,batteryExempt:false}),tick=ref(Date.now());
const visible=computed(()=>items.value.filter(item=>(filter.value==='trash'?!!item.trashed:!item.trashed&&(filter.value==='all'||filter.value==='unread'&&item.unread>0||filter.value==='open'&&item.status==='open'||filter.value==='resolved'&&item.status==='resolved'))&&item.email.toLowerCase().includes(search.value.toLowerCase())));
const current=computed(()=>items.value.find(item=>item.id===selected.value));
const unread=computed(()=>items.value.reduce((sum,item)=>sum+(item.trashed?0:item.unread),0));
const trashAvailable=ref(false);
const trashCount=computed(()=>items.value.filter(item=>item.trashed).length);
const trashTarget=ref<{owner:string;email:string;through:number}>(),trashBusy=ref(false),trashError=ref(''),notice=ref('');
function chooseFilter(value:string){filter.value=value;selected.value='';notice.value='';}
function askTrash(){if(trashAvailable.value&&current.value){trashTarget.value={owner:current.value.id,email:current.value.email,through:current.value.lastId};trashError.value='';}}
async function moveToTrash(){if(!trashAvailable.value||!trashTarget.value||trashBusy.value)return;trashBusy.value=true;trashError.value='';try{await feedbackCall('trashConversation',{owner:trashTarget.value.owner,through:trashTarget.value.through});trashTarget.value=undefined;selected.value='';notice.value='已移入回收站，30天内可恢复。';await refresh();}catch(exc){trashError.value=(exc as Error).message;}finally{trashBusy.value=false;}}
async function restore(){const owner=current.value?.id;if(!trashAvailable.value||!owner)return;await act(async()=>{await feedbackCall('restoreConversation',{owner});filter.value='all';await refresh();selected.value=owner;notice.value='会话已恢复。';});}
function trashDeadline(value:number){return new Date(value*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
const pairRemaining=computed(()=>Math.max(0,Math.ceil((pairExpires.value-tick.value)/1000)));
let timer:ReturnType<typeof setInterval>|undefined,clock:ReturnType<typeof setInterval>|undefined,unsubscribe=()=>{},refreshing=false;
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(exc){error.value=(exc as Error).message;}finally{busy.value=false;}}
async function refresh(){if(refreshing)return;refreshing=true;try{const [health,result]=await Promise.all([feedbackCall<FeedbackHealth>('health'),feedbackCall<{conversations:FeedbackSummary[]}>('conversations')]);trashAvailable.value=supportsFeedbackTrash(health);if(!trashAvailable.value&&filter.value==='trash'){filter.value='all';selected.value='';}const next=result.conversations;if(selected.value&&!next.some(item=>item.id===selected.value&&!!item.trashed===(filter.value==='trash')))selected.value='';items.value=next;error.value='';}catch(exc){error.value=(exc as Error).message;}finally{refreshing=false;}}
async function connect(){await act(async()=>{if(mobile.value)await feedbackCall('pair',{code:code.value,name:'小米／红米管理端'});else await feedbackCall('connect',{baseUrl:server.value,token:token.value});token.value='';code.value='';connected.value=true;await refresh();});}
function theme(){document.documentElement.dataset.theme=dark.value?'dark':'light';localStorage.setItem('feedback-theme',dark.value?'dark':'light');}
async function openSettings(){settings.value=true;await act(async()=>{devices.value=(await feedbackCall<{devices:Device[]}>('listDevices')).devices;if(mobile.value)receiving.value=await feedbackCall<Receiving>('receivingStatus');});}
async function pair(){await act(async()=>{const r=await feedbackCall<{code:string;expiresIn:number}>('createPairing');pairCode.value=r.code;pairExpires.value=Date.now()+r.expiresIn*1000;});}
async function revoke(d:Device){if(!confirm('撤销这台设备的访问权限？这台设备需要重新配对。'))return;await act(async()=>{await feedbackCall('revokeDevice',{deviceId:d.id});devices.value=(await feedbackCall<{devices:Device[]}>('listDevices')).devices;});}
async function receive(enabled:boolean){await act(async()=>{receiving.value=await feedbackCall<Receiving>('setReceiving',{enabled});});}
async function nativeSetting(kind:string){await act(async()=>{await feedbackCall('openSettings',{kind});});}
async function resume(){if(mobile.value&&settings.value)receiving.value=await feedbackCall<Receiving>('receivingStatus');if(connected.value)void refresh();}
onMounted(async()=>{theme();try{const i=await feedbackCall<FeedbackIdentity>('status');mobile.value=i.platform==='android';server.value=i.baseUrl;connected.value=i.connected;if(i.connected)await refresh();}catch(exc){error.value=(exc as Error).message;}unsubscribe=onFeedbackNotification(e=>{if(e.kind==='conversation_deleted'&&e.owner){void clearDeletedDraft(e.owner).then(refresh);}else if(['daily_feedback','new_feedback','conversation_changed','conversation_trashed','conversation_restored','conversation_deleted'].includes(e.kind))void refresh();else if(e.kind==='connection')online.value=!!e.online;else if(e.kind==='identity_lost'){connected.value=false;selected.value='';error.value='这台设备的授权已失效，请重新配对。';}else if(e.kind==='receiving_changed')void resume();});timer=setInterval(()=>{if(connected.value)void refresh();},30000);clock=setInterval(()=>tick.value=Date.now(),1000);document.addEventListener('visibilitychange',resume);});
onUnmounted(()=>{clearInterval(timer);clearInterval(clock);unsubscribe();document.removeEventListener('visibilitychange',resume);});
</script>
<template>
<main :class="['feedback-manager',{'has-selection':!!current}]">
<header class="manager-header"><div class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 3v-3a2 2 0 0 1-2-2V6a2 2 0 0 1 3-2Z"/><path d="M7 9h10M7 13h7"/></svg></div><div class="brand-copy"><h1>反馈收件箱</h1><p>PhoneticToolbox <span :class="{online}">{{online?'实时接收中':connected?'已连接':'等待连接'}}</span></p></div><div class="manager-author"><img :src="feedbackAuthor.avatar" :alt="feedbackAuthor.name+'的头像'"/><span>{{feedbackAuthor.name}}</span></div><button @click="dark=!dark;theme()" :aria-label="dark?'切换浅色主题':'切换深色主题'">{{dark?'☀':'☾'}}</button><button v-if="connected" @click="openSettings">设置</button></header>
<p v-if="error" class="manager-error" role="alert">{{error}}</p>
<form v-if="!connected" class="manager-connect" @submit.prevent="connect"><div class="welcome-symbol" aria-hidden="true">↗</div><p class="eyebrow">{{mobile?'随手回复，让交流继续':'每一条反馈，都有回应'}}</p><h2>{{mobile?'连接你的收件箱':'欢迎回来'}}</h2><p class="muted">{{mobile?'在电脑反馈管理工具的设置中生成配对码。首次配对后会保持登录。':'用户的留言与图片会汇集到这里。手机和电脑可以接力回复。'}}</p><label v-if="mobile">8 位配对码<input v-model="code" class="code-input" inputmode="numeric" pattern="[0-9]{8}" required minlength="8" maxlength="8" placeholder="00000000" autocomplete="off"/></label><template v-else><label>服务器地址<input v-model="server" type="url" required/></label><label>管理员凭据<input v-model="token" type="password" autocomplete="off" required minlength="32" maxlength="128"/></label></template><button class="primary" :disabled="busy">{{busy?'正在连接…':mobile?'配对并保持登录':'连接收件箱'}}</button><small class="muted">登录信息仅保存在此设备的系统加密存储中。</small></form>
<template v-else><nav class="manager-sections" aria-label="管理功能"><button :aria-pressed="section==='feedback'" @click="section='feedback'">用户反馈</button><button :aria-pressed="section==='web'" @click="section='web'">扩容与服务器</button></nav><div v-show="section==='web'" class="manager-operations"><WebOperations :active="section==='web'"/></div><div v-show="section==='feedback'" class="manager-body"><aside class="conversation-sidebar"><div class="inbox-heading"><h2>{{filter==='trash'?'回收站':'会话'}}</h2><span>{{filter==='trash'?trashCount+' 会话':unread+' 未读'}}</span><button @click="refresh" aria-label="刷新会话">↻</button></div><input v-model="search" type="search" placeholder="搜索联系邮箱" aria-label="搜索反馈邮箱"/><div class="filter-tabs" role="group" aria-label="会话筛选"><button v-for="f in [['all','全部'],['unread','未读'],['open','待处理'],['resolved','已解决'],['trash','回收站']]" :key="f[0]" :class="{active:filter===f[0]}" :disabled="f[0]==='trash'&&!trashAvailable" @click="chooseFilter(f[0]!)">{{f[1]}}</button></div><div class="conversation-list"><button v-for="item in visible" :key="item.id" :class="['conversation-item',{selected:item.id===selected}]" @click="selected=item.id"><span class="avatar">{{item.email.slice(0,1).toUpperCase()}}</span><span class="conversation-copy"><strong>{{item.email}}</strong><span>{{item.trashed?'已删除':item.status==='resolved'?'已解决':'待处理'}} · {{feedbackTime(item.trashed?item.deletedAt!:item.updated)}}</span><span class="conversation-source">{{feedbackClientLabel(item.client)}}</span></span><b v-if="item.unread&&!item.trashed" class="badge">{{item.unread}}</b></button><div v-if="!visible.length" class="list-empty"><span aria-hidden="true">✉</span><p>{{filter==='trash'?'回收站为空':items.some(item=>!item.trashed)?'没有符合条件的会话':'收件箱很安静'}}</p><small>{{filter==='trash'?'删除的会话保留30天，到期永久删除。':'有新留言时会在这里出现。'}}</small></div></div><footer class="sidebar-footer"><span :class="['connection-dot',{online}]"></span>{{online?'新留言自动送达':'正在等待通知连接'}}<small>每天 09:00 补充检查</small></footer></aside>
<section class="manager-conversation"><template v-if="current"><header class="conversation-heading"><button class="back-button" @click="selected=''" aria-label="返回会话列表">‹</button><span class="avatar">{{current.email.slice(0,1).toUpperCase()}}</span><div><h2>{{current.email}}</h2><small class="muted">{{current.email_verified?'邮箱已验证':'联系邮箱未验证'}} · {{current.trashed?'回收站':current.status==='resolved'?'已解决':'交流中'}}</small><p class="conversation-source muted">最近留言：{{feedbackClientLabel(current.client)}}</p></div></header><p v-if="current.trashed&&current.purgeAt" class="trash-notice">将于 {{trashDeadline(current.purgeAt)}} 永久删除。30天内可恢复，用户再次留言时会自动恢复。</p><FeedbackThread ref="feedbackThread" :key="current.id" admin :owner="current.id" :trashed="!!current.trashed" :trash-available="trashAvailable" :management-busy="busy||trashBusy" @updated="refresh" @trash="askTrash" @restore="restore"/></template><div v-else class="manager-empty"><div class="empty-illustration" aria-hidden="true"><svg viewBox="0 0 120 100" fill="none"><rect x="16" y="16" width="88" height="63" rx="15" fill="var(--teal-bg)" stroke="var(--teal)" stroke-width="2"/><path d="m24 28 36 27 36-27" stroke="var(--teal)" stroke-width="2"/><circle cx="96" cy="77" r="17" fill="var(--panel)" stroke="var(--teal)" stroke-width="2"/><path d="M88 77h16m-8-8v16" stroke="var(--teal)" stroke-width="2"/></svg></div><h2>留一个回应的位置</h2><p>选择一段会话，查看问题、截图与历史回复。</p><span>回复同步到用户应用，邮件提醒遵循用户的选择。</span></div></section></div></template>
<p v-if="notice" class="manager-notice" role="status">{{notice}}</p>
</main>
<ModalDialog v-if="trashTarget" title="删除会话" variant="confirm" :close-disabled="trashBusy" @close="trashTarget=undefined"><p>将 {{trashTarget.email}} 的会话移入回收站？</p><p>30天内可以查看和恢复，到期后会永久删除全部消息和图片。</p><p v-if="trashError" class="manager-error" role="alert">{{trashError}}</p><template #footer><button :disabled="trashBusy" @click="trashTarget=undefined">取消</button><button class="danger" :disabled="trashBusy" @click="moveToTrash">{{trashBusy?'正在移动…':'移入回收站'}}</button></template></ModalDialog>
<ModalDialog v-if="settings" title="收件箱设置" @close="settings=false;pairCode=''"><div class="manager-settings">
<section v-if="mobile"><h3>消息提醒</h3><p class="muted">后台接收开启时，通知栏会显示接收状态。有新反馈时会单独提醒。</p><button class="primary" :disabled="busy" @click="receive(!receiving.enabled)">{{receiving.enabled?'停止后台接收':'开启后台接收'}}</button><p :class="receiving.permission?'muted':'manager-error'">{{receiving.permission?'通知权限已开启':'请允许通知，才能收到消息提醒。'}}</p><button @click="nativeSetting('notifications')">通知设置</button></section>
<section v-if="mobile"><h3>小米／红米后台设置</h3><p>开启自启动，将省电策略设为无限制，并在最近任务中锁定应用。</p><div class="settings-buttons"><button @click="nativeSetting('autostart')">自启动设置</button><button @click="nativeSetting('battery')">省电设置</button><button @click="nativeSetting('app')">应用详情</button></div><small class="muted">入口名称可能随系统版本变化。强行停止应用后，需要重新打开。</small></section>
<section v-else><h3>配对手机</h3><p class="muted">在安卓应用中输入配对码。有效期 5 分钟，只能使用一次。</p><button :disabled="busy" class="primary" @click="pair">{{pairCode?'生成新配对码':'生成配对码'}}</button><div v-if="pairCode&&pairRemaining" class="pairing-display"><strong>{{pairCode}}</strong><small>{{pairRemaining}} 秒后过期</small></div><p v-else-if="pairCode" class="muted">配对码已过期，请重新生成。</p></section>
<section><h3>已配对设备</h3><p v-if="!devices.length" class="muted">还没有配对手机。</p><div v-for="device in devices" :key="device.id" class="device-row"><div><strong>{{device.name}}</strong><small>{{feedbackTime(device.created)}} 配对</small></div><button :disabled="busy" @click="revoke(device)">撤销</button></div></section><p v-if="error" class="manager-error" role="alert">{{error}}</p><button v-if="!mobile" @click="feedbackCall('windowAction',{action:'quit'})">退出工具</button><p class="muted" v-if="!mobile">关闭电脑窗口后仍会在托盘中接收提醒。要结束接收，请从托盘选择退出。</p>
</div></ModalDialog>
</template>
<style scoped>
.trash-notice{color:var(--muted);font-size:.78rem;margin:0;line-height:1.6}.manager-notice{padding:8px 20px;margin:0;color:var(--teal);font-size:.85rem;background:var(--panel)}.filter-tabs{flex-wrap:wrap}.filter-tabs button{flex:1 1 auto}
.conversation-source{margin:5px 0 0;font-size:.75rem;overflow-wrap:anywhere;line-height:1.5}
.manager-operations{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden}.manager-sections{display:flex;gap:4px;padding:6px 20px;border-bottom:1px solid var(--border);flex:none;background:var(--panel)}.manager-sections button{border-color:transparent;background:transparent;border-radius:8px;font-size:.86rem;padding:7px 16px}.manager-sections button[aria-pressed=true]{background:var(--selected);color:var(--accent);font-weight:600}.manager-sections button[aria-pressed=true]:before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}
.feedback-manager{height:100dvh;display:flex;flex-direction:column;background:var(--app);overflow:hidden;--accent:var(--teal);--selected:var(--teal-bg);--on-accent:var(--panel)}.feedback-manager:has(.manager-connect){overflow:auto}.manager-header{flex-shrink:0;display:flex;align-items:center;gap:12px;padding:12px 20px;background:var(--panel);border-bottom:1px solid var(--border)}.brand-mark{width:44px;height:44px;border-radius:13px;background:var(--teal-bg);color:var(--teal);display:grid;place-items:center}.brand-mark svg{width:25px;height:25px}.brand-copy{flex:1}.manager-author{display:flex;align-items:center;gap:8px;font-size:.85rem}.manager-author img{width:34px;height:34px;border-radius:50%;object-fit:cover;object-position:50% 32%;border:1px solid var(--border)}.brand-copy h1{font-size:1.25rem;font-weight:650;margin:0 0 4px}.brand-copy p{font-size:.76rem;color:var(--muted);margin:0}.brand-copy p span{margin-left:8px}.online{color:var(--teal)}.manager-error{color:var(--danger);padding:8px 18px;margin:0;font-size:.88rem}.manager-body{display:grid;grid-template-columns:280px minmax(0,1fr);min-height:0;flex:1}.conversation-sidebar{display:flex;flex-direction:column;gap:12px;min-height:0;padding:18px 14px 10px;border-right:1px solid var(--border);background:var(--panel)}.inbox-heading{display:flex;align-items:center;gap:10px}.inbox-heading h2{font-size:1.1rem;margin:0;flex:1}.inbox-heading>span{font-size:.78rem;background:var(--teal-bg);color:var(--teal);border-radius:20px;padding:4px 9px}.filter-tabs{display:flex;gap:3px;background:var(--app);padding:4px;border-radius:9px}.filter-tabs button{flex:1;border:0;font-size:.8rem;min-height:30px;background:transparent;padding:4px}.filter-tabs button.active{background:var(--panel);color:var(--teal);box-shadow:0 1px 4px #00000010}.conversation-list{overflow:auto;flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}.conversation-item{display:flex;gap:11px;align-items:center;white-space:normal;width:100%;padding:13px